def forward(groups):
    try:
        value, unit = float(groups[1]), groups[2]
        scale = {'B': 1, 'KB': 1024, 'MB': 1024 ** 2}
        if unit not in scale:
            raise ValueError(f"Unknown unit: {unit}")
        canonical_value = int(value * scale[unit])
        return {'stored': [canonical_value], 'layout': [unit]}
    except ValueError as e:
        raise ValueError(f"Error processing input: {e}")

def inverse(record):
    canonical_value, unit = record['stored'][0], record['layout'][0]
    scale = {'B': 1, 'KB': 1024, 'MB': 1024 ** 2}
    if unit not in scale:
        raise ValueError(f"Unknown unit: {unit}")
    value = canonical_value / scale[unit]
    return f"estimated size {value:.1f} {unit}"
